  });

  const invalidCases = [
    { input: '', label: 'empty string' },
    { input: '   ', label: 'whitespace only' },
    { input: 42, label: 'non-string' },
    { input: 'a'.repeat(201), label: 'titles over 200 characters' }
  ];

  for (const { input, label } of invalidCases) {
    test(`rejects ${label}`, () => {
      assert.strictEqual(validateTitle(input).valid, false);
    });
  }

